/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
/// Post purchase order confirmation
/// </summary>
class METPOConfirmationPost
{
}

Method.Source:
    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
    /// </summary>
    /// <param name="_company"> Get company</param>
    /// <param name="_purchId"> Get purchase order number</param>
    public void postConfirmation(DataAreaId _company, PurchId _purchId)
    {       
            
        changecompany(_company)
        {
            PurchTable  purchTable;
            select firstonly DocumentState from purchTable
                where purchTable.PurchId == _purchId;
            if(purchTable)
            {
                if(purchTable.DocumentState == VersioningDocumentState::Approved)
                {
                    PurchFormLetter purchFormLetter = PurchFormLetter::construct(DocumentStatus::PurchaseOrder);
                    try
                    {
                        purchFormLetter.update(purchTable,_purchId);
                        Info(strFmt("@MET:PurchaseOrderHasBeenConfirmed",_purchId));
                        
                    }                    
                    catch(Exception::CLRError)
                    {                        
                        System.Exception netExcepn = CLRInterop::getLastException();
                        error(netExcepn.Message);
                    
                        
                    }
                    catch(Exception::Error)
                    {
                        System.Exception ex = CLRInterop::getLastException();
                        error(ex.Message);                   
                        
                    } 
                }
                else
                {
                    error(strFmt("@MET:PurchaseOrderHasInvalidApprovalStatus",purchTable.PurchId,purchTable.DocumentState));
                }

            }
            else
            {
                error(strFmt("@MET:InvalidPurchaseOrderNumber",_purchId));
            }
        }
                    
    }
